"""Independent reference implementation for testing (slow, direct, obvious)."""
from fractions import Fraction
import itertools

def align8(x): return (x + 7) & ~7
def align64(x): return (x + 63) & ~63

def ref_g(fib, b, e):
    """Stage usage for interval (b,e], straight from the definition."""
    if b == 0:
        nodes = [0]
    else:
        nodes = sorted({a >> (128 - b) for (a, L, h) in fib if L > b})
    U = 0
    for key in nodes:
        rc = 0
        for (a, L, h) in fib:
            if (a >> (128 - b)) == key and b < L <= e:
                rc += 32 + align8(L - b)
        if b == 0:
            for (a, L, h) in fib:
                if L == 0:
                    rc += 32 + align8(0)
        ec = 0
        if e < 128:
            seen = set()
            for (a, L, h) in fib:
                if L > e and (a >> (128 - b)) == key:
                    seen.add(a >> (128 - e))
            ec = len(seen)
        U += align64(128 + rc + ec * (32 + align8(e - b)))
    return U

def ref_solve(fib, caps, stride):
    """Reference DP with exact Fractions and a directly computed g table."""
    S = len(caps)
    g = {}
    for b in range(128):
        for e in range(b + 1, min(128, b + stride) + 1):
            g[(b, e)] = ref_g(fib, b, e)
    best = [[None] * 129 for _ in range(S)]
    for d in range(1, min(stride, 128) + 1):
        u = g[(0, d)]
        if u <= caps[0]:
            best[0][d] = Fraction(u, caps[0])
    for s in range(1, S):
        for d in range(1, 129):
            for p in range(max(0, d - stride), d):
                pb = best[s - 1][p]
                if pb is None:
                    continue
                u = g[(p, d)]
                if u > caps[s]:
                    continue
                cand = max(pb, Fraction(u, caps[s]))
                if best[s][d] is None or cand < best[s][d]:
                    best[s][d] = cand
    return best[S - 1][128]

def enum_solve(fib, caps, stride):
    """Gold standard: enumerate every cut vector."""
    S = len(caps)
    bestv = None
    bestcuts = None
    def rec(i, prev, cuts):
        nonlocal bestv, bestcuts
        if i == S:
            if cuts[-1] != 128:
                return
            peak = Fraction(0)
            ok = True
            for j in range(S):
                u = ref_g(fib, cuts[j], cuts[j + 1])
                if u > caps[j]:
                    ok = False
                    break
                peak = max(peak, Fraction(u, caps[j]))
            if ok and (bestv is None or peak < bestv):
                bestv = peak
                bestcuts = list(cuts)
            return
        # remaining stages must be able to reach 128
        for d in range(prev + 1, min(128, prev + stride) + 1):
            if 128 - d < S - i:
                continue
            if (S - i) * stride < 128 - d:
                continue
            cuts.append(d)
            rec(i + 1, d, cuts)
            cuts.pop()
    rec(0, 0, [0])
    return bestv, bestcuts

def ref_lpm(fib, addr):
    best = None
    for (a, L, h) in fib:
        if (addr >> (128 - L)) == (a >> (128 - L)):
            if best is None or L > best[1]:
                best = (h, L)
    return best
